from typing import List
import bisect

class Solution:
    def minDifference(self, nums: List[int]) -> int:
        n = len(nums)
        base = 0
        crit = []
        for i, a in enumerate(nums):
            if a == -1:
                continue
            if i > 0 and nums[i - 1] != -1:
                base = max(base, abs(a - nums[i - 1]))
            if i + 1 < n and nums[i + 1] == -1:
                crit.append(a)
        if not crit:
            return base
        crit.sort()

        def feasible(d: int) -> bool:
            arr = crit
            for _ in range(2):
                if not arr:
                    return True
                lim = arr[0] + 2 * d
                idx = bisect.bisect_right(arr, lim)
                arr = arr[idx:]
            return not arr

        lo, hi = base, crit[-1] - crit[0]
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

