class Solution {
public:
    int minDifference(vector<int>& nums) {
        int n = nums.size();
        long long base = 0;
        vector<long long> crit;
        for (int i = 0; i < n; i++) {
            if (nums[i] == -1) continue;
            if (i > 0 && nums[i-1] != -1)
                base = max(base, (long long)abs(nums[i] - nums[i-1]));
            if (i + 1 < n && nums[i+1] == -1)
                crit.push_back(nums[i]);
        }
        if (crit.empty()) return base;
        sort(crit.begin(), crit.end());
        auto feasible = [&](long long d) {
            int idx = 0;
            for (int k = 0; k < 2 && idx < (int)crit.size(); k++) {
                long long lim = crit[idx] + 2 * d;
                while (idx < (int)crit.size() && crit[idx] <= lim) idx++;
            }
            return idx == (int)crit.size();
        };
        long long lo = base, hi = crit.back() - crit.front();
        while (lo < hi) {
            long long mid = (lo + hi) / 2;
            if (feasible(mid)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};

