import java.util.*;

class Solution {
    public int minDifference(int[] nums) {
        int n = nums.length;
        long base = 0;
        List<Long> crit = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (nums[i] == -1) continue;
            if (i > 0 && nums[i-1] != -1)
                base = Math.max(base, Math.abs((long) nums[i] - nums[i-1]));
            if (i + 1 < n && nums[i+1] == -1)
                crit.add((long) nums[i]);
        }
        if (crit.isEmpty()) return (int) base;
        Collections.sort(crit);
        int m = crit.size();
        java.util.function.LongPredicate feasible = d -> {
            int idx = 0;
            for (int k = 0; k < 2 && idx < m; k++) {
                long lim = crit.get(idx) + 2 * d;
                while (idx < m && crit.get(idx) <= lim) idx++;
            }
            return idx == m;
        };
        long lo = base, hi = crit.get(m - 1) - crit.get(0);
        while (lo < hi) {
            long mid = (lo + hi) / 2;
            if (feasible.test(mid)) hi = mid;
            else lo = mid + 1;
        }
        return (int) lo;
    }
}

